import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { dashboardApi, machineApi } from '../api/client';

// 15 Key Industrial Digital Twin Control Center Components
import SystemStatusBar from '../components/SystemStatusBar';
import EnhancedKPICards from '../components/EnhancedKPICards';
import FactoryDigitalTwinGrid from '../components/FactoryDigitalTwinGrid';
import ProductionMonitoringCard from '../components/ProductionMonitoringCard';
import LiveSensorWidgets from '../components/LiveSensorWidgets';
import EnergyDashboardCard from '../components/EnergyDashboardCard';
import AIIntelligenceCard from '../components/AIIntelligenceCard';
import MaintenanceTimelineCard from '../components/MaintenanceTimelineCard';
import FactoryOverviewCard from '../components/FactoryOverviewCard';

import StatusChart from '../components/StatusChart';
import ActivityFeed from '../components/ActivityFeed';
import CriticalityChart from '../components/CriticalityChart';
import ProductionChart from '../components/ProductionChart';
import HealthTrendChart from '../components/HealthTrendChart';
import AlertsPanel from '../components/AlertsPanel';
import SkeletonCard from '../components/SkeletonCard';
import MachineDetailsModal from '../components/MachineDetailsModal';

import {
  Server,
  Plus,
  Radio,
  ArrowRight,
  Sparkles,
  Download,
  Activity,
  Cpu,
} from 'lucide-react';

const DashboardPage = () => {
  const navigate = useNavigate();
  const [summary, setSummary] = useState(null);
  const [fleetStatus, setFleetStatus] = useState(null);
  const [recentActivities, setRecentActivities] = useState([]);
  const [machinesList, setMachinesList] = useState([]);
  const [loading, setLoading] = useState(true);

  // Detail View State
  const [selectedMachineDetail, setSelectedMachineDetail] = useState(null);

  useEffect(() => {
    fetchDashboardData();
    const interval = setInterval(fetchDashboardData, 30000);
    return () => clearInterval(interval);
  }, []);

  const fetchDashboardData = async () => {
    try {
      setLoading(true);
      const [sumRes, fleetRes, actRes, machRes] = await Promise.allSettled([
        dashboardApi.getSummary(),
        dashboardApi.getFleetStatus(),
        dashboardApi.getRecentActivity(),
        machineApi.getAllMachines(),
      ]);

      if (sumRes.status === 'fulfilled' && sumRes.value.data.success) {
        setSummary(sumRes.value.data.data);
      }
      if (fleetRes.status === 'fulfilled' && fleetRes.value.data.success) {
        setFleetStatus(fleetRes.value.data.data);
      }
      if (actRes.status === 'fulfilled' && actRes.value.data.success) {
        setRecentActivities(actRes.value.data.data || []);
      }
      if (machRes.status === 'fulfilled' && machRes.value.data.success) {
        setMachinesList(machRes.value.data.data || []);
      }
    } catch (err) {
      console.error('Error fetching dashboard summary:', err);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div>
      {/* 1. Live System Status Bar (Section 3) */}
      <SystemStatusBar />

      {/* Hero Control Header */}
      <div className="page-header" style={{ marginBottom: '1.25rem' }}>
        <div className="page-title-group">
          <div style={{ display: 'flex', alignItems: 'center', gap: '0.75rem' }}>
            <h1>🏭 TexTwin Industrial Digital Twin Operating System</h1>
            <span className="badge badge-running" style={{ fontWeight: '800' }}>
              <Radio size={12} className="dot" /> REAL-TIME SSE SYNC
            </span>
          </div>
          <p>Real-Time State Mirroring Across 6 Factory Hubs, 10 Lines, & 20 Weaving Looms</p>
        </div>

        <div style={{ display: 'flex', gap: '0.75rem', flexWrap: 'wrap' }}>
          <button className="btn btn-secondary" onClick={() => navigate('/what-if')}>
            <Sparkles size={16} style={{ color: 'var(--accent-primary)' }} /> What-If AI Simulator
          </button>
          <button className="btn btn-secondary" onClick={() => navigate('/assets')}>
            View Asset Inventory <ArrowRight size={16} />
          </button>
          <button className="btn btn-primary" onClick={() => navigate('/assets/new')}>
            <Plus size={16} /> Add Asset
          </button>
        </div>
      </div>

      {/* 2. Improved KPI Cards (Section 2) */}
      <EnhancedKPICards summary={summary} />

      {/* 3. Factory Digital Twin Layout Section (Section 1) */}
      <FactoryDigitalTwinGrid machines={machinesList} />

      {/* 4. Production Monitoring (Section 4) */}
      <ProductionMonitoringCard />

      {/* 5. Live Sensor Widgets (Section 5) */}
      <LiveSensorWidgets />

      {/* 6. Energy Dashboard (Section 6) */}
      <EnergyDashboardCard />

      {/* 7. AI Intelligence & RUL Section (Section 7) */}
      <AIIntelligenceCard />

      {/* 8. Fleet Status & Recent Activity Stream (Section 8) */}
      <div
        style={{
          display: 'grid',
          gridTemplateColumns: 'repeat(auto-fit, minmax(320px, 1fr))',
          gap: '1.25rem',
          marginBottom: '1.75rem',
          alignItems: 'stretch',
        }}
      >
        {/* Panel 1: Status Breakdown */}
        <div className="glass-card" style={{ padding: '1.25rem' }}>
          <StatusChart
            running={fleetStatus?.running || summary?.running || 16}
            idle={fleetStatus?.idle || summary?.idle || 2}
            maintenance={fleetStatus?.maintenance || summary?.maintenance || 2}
          />
        </div>

        {/* Panel 2: Recent Activity Audit Feed (Section 8) */}
        <div className="glass-card" style={{ padding: '1.25rem' }}>
          <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '0.75rem' }}>
            <div>
              <h3 style={{ fontSize: '1rem', fontWeight: '800', color: 'var(--text-primary)' }}>
                Recent Activity Audit Stream
              </h3>
              <span style={{ fontSize: '0.74rem', color: 'var(--text-muted)', fontWeight: '600' }}>
                Latest Operational Audit & Sensor Events
              </span>
            </div>
            <span className="badge badge-low" style={{ fontWeight: '800', fontSize: '0.7rem' }}>Audit Trail</span>
          </div>
          <ActivityFeed activities={recentActivities} />
        </div>

        {/* Panel 3: Criticality Distribution */}
        <CriticalityChart
          high={summary?.highCriticality || 3}
          medium={6}
          low={11}
        />
      </div>

      {/* 9. Maintenance Timeline (Section 9) */}
      <MaintenanceTimelineCard />

      {/* 10. Factory Overview (Section 10) */}
      <FactoryOverviewCard />

      {/* 11. Alert Center (Section 11) */}
      <div style={{ marginBottom: '1.75rem' }}>
        <AlertsPanel />
      </div>

      {/* 12. Analytics Charts (Section 12) */}
      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(400px, 1fr))', gap: '1.5rem', marginBottom: '1.75rem' }}>
        <ProductionChart />
        <HealthTrendChart />
      </div>

      {/* Machine Details Modal */}
      {selectedMachineDetail && (
        <MachineDetailsModal
          machine={selectedMachineDetail}
          onClose={() => setSelectedMachineDetail(null)}
        />
      )}
    </div>
  );
};

export default DashboardPage;
